groundTexture.wrapS = groundTexture.wrapT = T.RepeatWrapping;
groundTexture.repeat.set(7,7);
const ground = new T.Mesh(
  new T.CircleGeometry(28, 96),
  new T.MeshStandardMaterial({ map:groundTexture, color: 0x8b909b, roughness: 0.96, metalness: 0.02 })
);
ground.rotation.x = -Math.PI / 2; ground.receiveShadow = true; scene.add(ground);
const innerGlow = new T.Mesh(
  new T.CircleGeometry(9, 64),
  new T.MeshBasicMaterial({ color: 0x47caa0, transparent: true, opacity: 0.08 })
);
