const ring = new T.Mesh(new T.RingGeometry(7.98, 8.02, 96), new T.MeshBasicMaterial({ color: 0xc6d2d3, transparent: true, opacity: 0.22, side: T.DoubleSide }));
ring.rotation.x = -Math.PI / 2; ring.position.y = 0.03; scene.add(ring);
const rune = new T.Mesh(new T.RingGeometry(1.55, 1.75, 48), new T.MeshBasicMaterial({ color: 0x46ffe0, transparent: true, opacity: 0.6, side: T.DoubleSide }));
rune.rotation.x = -Math.PI / 2; rune.position.y = 0.04; scene.add(rune);

