  ftRunes.forEach((g,i)=>{ const a=i*Math.PI/2; const rr=1.25+(tier-1)*0.06; g.position.set(Math.cos(a)*rr,1.35+(tier-1)*0.18,Math.sin(a)*rr); g.scale.setScalar(0.8+(tier-1)*0.18+minor*0.05); g.visible=tier>=2; g.material.emissiveIntensity=0.8+tier*0.35; });
  ftLowerBand.position.y=0.72; ftLowerBand.scale.setScalar(1+(tier-1)*0.07); ftLowerBand.visible=tier>=2;
