  ftCrownBand.position.y=topY+0.48; ftCrownBand.scale.setScalar(1+(tier-1)*0.07+minor*0.03);
  ftDoor.position.set(0,0.72,1.43); ftDoor.scale.set(1+(tier-1)*0.03,1+(tier-1)*0.05,1);
  ftDoorArch.position.set(0,1.10,1.48); ftDoorArch.scale.setScalar(1+(tier-1)*0.05);
  ftFrontGem.position.set(0,1.70+(tier-1)*0.14,1.34+(tier-1)*0.04); ftFrontGem.scale.setScalar(0.88+(tier-1)*0.14+minor*0.05); ftFrontGem.material.emissiveIntensity=1.3+tier*0.28;
  ftTopGem.position.set(0,topY+0.62,1.26); ftTopGem.scale.setScalar(0.78+(tier-1)*0.12); ftTopGem.material.emissiveIntensity=1.35+tier*0.25;
  ftTorches[0].position.set(-0.48,0.86,1.52); ftTorches[1].position.set(0.48,0.86,1.52); ftTorches.forEach((f,i)=>{f.scale.setScalar(0.9+Math.sin(t*7+i)*0.08); f.material.emissiveIntensity=2.0+tier*0.22;});
  const plinthR=1.82+(tier-1)*0.10;
  ftPlinths.forEach((pg,i)=>{ const a=i*Math.PI/2+Math.PI/4; pg.position.set(Math.cos(a)*plinthR,0.42,Math.sin(a)*plinthR); pg.scale.setScalar(0.86+(tier-1)*0.07+minor*0.03); pg.visible=tier>=2 || i<2; });
  fantasyTower.scale.setScalar(1.0 + minor*0.015);
