  sideBladeL.rotation.z = -0.68; sideBladeR.rotation.z = 0.68;
  sideBladeL.scale.set(1, 1 + Math.max(0,m.tier - 2) * 0.18 + minor * 0.1, 1); sideBladeR.scale.copy(sideBladeL.scale);
  sideBladeL.visible = sideBladeR.visible = m.tier >= 2;
  orbL.position.set(-0.7, m.capY + 0.14 + minor * 0.05, 0.24);
