function updateTowerVisuals(){
  const tier = getTowerTier();
  towerState.tier = tier;
  towerArtMaterial.map = towerAtlas.frames[tier-1];
  for(const child of core.children) child.visible = child === towerArt;
  // Live weapon modules appear only once their upgrade is unlocked.
  teslaLeft.position.set(-2.0,1.45,0.35); teslaRight.position.set(2.0,1.45,0.35);
  fireballCannon.position.set(-1.75,1.6,0.65);
  updateTeslaVisuals(); updateFireballVisuals();
  updateTowerDeck();
  if(hero){
    hero.userData.currentGameScale = (hero.userData.baseInGameScale || 1.22) * 0.48;
    hero.scale.setScalar(hero.userData.currentGameScale);
    hero.position.copy(towerDeckPosition);
  }
  if(heroAura) heroAura.visible = false;
  rune.visible = false;
  innerGlow.material.opacity = 0.025;
  coreLight.position.copy(towerDeckPosition); coreLight.intensity = 1.4;
}
function updateTowerDeck(){
  referenceArt.deckPosition(towerArt, cam, towerState.tier, towerDeckPosition);
  towerState.topY = towerDeckPosition.y;
  screenUp.setFromMatrixColumn(cam.matrixWorld,1);
  screenRight.setFromMatrixColumn(cam.matrixWorld,0);
}
function refreshArtworkStatus(){
  const status = $('artworkStatus');
  const failed = [mageAtlas,towerAtlas].some(atlas => atlas.status === 'error');
  const ready = [mageAtlas,towerAtlas].every(atlas => atlas.status === 'ready');
  if(status){
    status.hidden = ready;
    status.textContent = failed ? 'Chưa tải được hình ảnh. Bấm Tải lại để thử lại.' : 'Đang tải nhân vật và tháp…';
  }
  const retry = $('retryArtwork'); if(retry)retry.hidden = !failed;
  const confirm = $('confirmHero'); if(confirm)confirm.disabled = !ready;
}
function heroShootOrigin(offsetY = 0.92){
  updateTowerDeck();
  if(s.hero === 'frost') return towerDeckPosition.clone().addScaledVector(screenUp,offsetY*1.9).addScaledVector(screenRight,0.55);
  return towerDeckPosition.clone().add(new T.Vector3(0,offsetY,0.08));
}

function makeTree(x,z,scale){
  const g = new T.Group();
  const trunk = new T.Mesh(new T.CylinderGeometry(0.08*scale, 0.12*scale, 0.9*scale, 6), new T.MeshStandardMaterial({ color: 0x3b2e22, roughness: 0.95 }));
  trunk.position.y = 0.45 * scale; trunk.castShadow = true; g.add(trunk);
  const top = new T.Mesh(new T.ConeGeometry(0.42*scale, 1.2*scale, 7), new T.MeshStandardMaterial({ color: 0x4f6260, roughness: 1 }));
  top.position.y = 1.22 * scale; top.castShadow = true; g.add(top);
  g.position.set(x, 0, z); scene.add(g);
}
function makeRock(x,z,scale){
  const rock = new T.Mesh(new T.DodecahedronGeometry(0.35*scale, 0), new T.MeshStandardMaterial({ color: 0x6f757c, roughness: 0.94 }));
  rock.position.set(x, 0.25*scale, z); rock.scale.set(1, 0.7 + Math.random()*0.8, 1); rock.rotation.set(Math.random(), Math.random(), Math.random()); rock.castShadow = true; rock.receiveShadow = true; scene.add(rock);
}
for(let i=0;i<60;i++){
  const a = Math.random()*Math.PI*2; const r = rand(12, 25); (Math.random()<0.55 ? makeRock : makeTree)(Math.cos(a)*r, Math.sin(a)*r, rand(0.65,1.45));
}

