  ctx.strokeStyle = key === 'frost' ? '#39475d' : key === 'fel' ? '#2d2a33' : key === 'archer' ? '#322740' : key === 'orc' ? '#4f3b2d' : '#43443b'; ctx.lineWidth = 14;
  ctx.beginPath(); ctx.moveTo(cx-36, 610); ctx.lineTo(cx-28, 525); ctx.stroke();
