  ctx.beginPath(); ctx.arc(cx, 392, key === 'orc' ? 10 : 12, 0, Math.PI*2); ctx.fill();
  ctx.fillStyle = 'rgba(255,255,255,0.8)'; ctx.beginPath(); ctx.arc(cx-5, 387, 4, 0, Math.PI*2); ctx.fill();

