  const mat = new T.MeshBasicMaterial({ map:loadHeroImageTexture(sc.urlBase+'/'+sc.animations.idle[0]), transparent:true, alphaTest:0.14, side:T.DoubleSide, depthWrite:false, depthTest:true, color:sc.tint });
  const plane = new T.Mesh(new T.PlaneGeometry(sc.width,sc.height),mat); plane.renderOrder=10; pivot.add(plane);
  const decor = null;
  const spriteCfg={ urlBase:sc.urlBase, animations:sc.animations, fps:sc.fps };
  g.userData.sprite={ cfg:spriteCfg, cache:{}, frames:[], frameIndex:0, timer:0, fps:sc.fps.idle, anim:'idle', material:mat, actionUntil:0 };
  g.userData.facePivot=pivot; g.userData.plane=plane; g.userData.isBillboardEnemy=true; g.userData.baseTint=sc.tint; g.userData.enemyDecor = decor;
