  if(s.hero === 'fel'){ s.tempFire = Math.max(s.tempFire, 1.25); s.tempUntil = Math.max(s.tempUntil, t + 1.2); }
  burst(e.g.position, e.kind === 'boss' ? 0xb775ff : 0xded6b2, e.kind === 'boss' ? 1.45 : 0.55);
