  const targetPos = targetE.g.position.clone().add(new T.Vector3(0, targetE.rad + 0.35, 0));
  aimFireballCannon(targetPos);
  fireballPulse=0.28; updateFireballVisuals();
  const start = fireballMuzzleWorld();
  const dir=targetPos.clone().sub(start).normalize();
  makeShot(start, dir, 0xff9131, 0.19+Math.min(s.fireball,6)*0.012, 7.5, s.damage * (1.7 + s.fireball * 0.5), 'fire', { blast: 1.8 + s.fireball * 0.18, life: 2.6, source:'fireball' });
  burst(start,0xff7a22,0.38+Math.min(s.fireball,5)*0.05);
