  let d = s.damage * (0.75 + s.tesla * 0.3);
  let prev=leftStart;
  for(const e of list){ const ep=e.g.position.clone().add(new T.Vector3(0,e.rad+0.35,0)); electricArc(prev,ep,0xb1f5ff,10); hit(e,d); d*=0.84; prev=ep; }
  if(s.tesla >= 2 && list.length){ const ep=list[0].g.position.clone().add(new T.Vector3(0,list[0].rad+0.35,0)); electricArc(rightStart,ep,0x7ee8ff,10); }
  burst(leftStart, 0x79edff, 0.42); if(s.tesla >= 2) burst(rightStart, 0x79edff, 0.42);
