  const h = HEROES[s.hero]; const sk = h.skills[i]; const cdScale = s.hero === 'shaman' ? 0.88 : 1; s.skillCd[i] = sk.cd * cdScale;
  triggerHeroAction('skill', s.hero === 'shaman' ? 0.75 : 0.5);
