    if(i === 0){ const es = nearest(8, s.range + 4); const points = [heroShootOrigin(0.95)]; es.forEach((e,j) => { hit(e, s.damage * (2.2 - j * 0.08)); e.slow = t + 2.8; points.push(e.g.position.clone().add(new T.Vector3(0, e.rad + 0.35, 0))); }); lightning(points, 0x65efad); }
    else if(i === 1){ s.shield = Math.min(s.maxHp, s.shield + s.maxHp * 0.45); burst(hero.position, 0x91ffca, 1.5); pulse(new T.Vector3(0,0,0), 0x65efad, 3.2); }
