  Object.assign(s, { maxHp:h.stats.hp, hp:h.stats.hp, damage:h.stats.damage, fireRate:h.stats.fireRate, range:h.stats.range, regen:h.stats.regen, crit:h.stats.crit, multishot:h.stats.multishot, shield:0, skillCd:[0,0,0], paused:false, over:false, tempDamage:1, tempFire:1, tempUntil:0, lifesteal:0, poisonUntil:0, summonUntil:0, heroBurst:0 });
