    const lv = s.up[key], cost = Math.round(base * Math.pow(1.38, lv));
    const row = document.createElement('div'); row.className = 'urow';
    row.innerHTML = `<span>${name}<br><small>Lv.${lv}</small></span><button ${s.gold < cost ? 'disabled' : ''}>${cost} G</button>`;
    row.querySelector('button').onclick = () => { if(s.over||!s.hero||s.gold < cost) return; s.gold -= cost; applyUpgrade(key, true); };
    ui.upgradeRows.appendChild(row);
