  ui.hpFill.style.width = clamp(s.hp / s.maxHp * 100, 0, 100) + '%'; ui.hpTxt.textContent = Math.ceil(s.hp) + ' / ' + s.maxHp + ' HP'; ui.xpFill.style.width = clamp(s.xp / s.xpNext * 100, 0, 100) + '%'; ui.xpTxt.textContent = Math.floor(s.xp) + ' / ' + s.xpNext + ' XP'; ui.pause.textContent = s.paused ? '▶' : 'Ⅱ';
